export class HttpError extends Error {
  constructor(status, code) {
    super(code);
    this.status = status;
    this.code = code;
  }
}

export function assertCanPublish(seller, listing) {
  if (listing.isDemo) return;
  if (!seller.identityVerified) {
    throw new HttpError(403, "seller.identity_unverified");
  }
}

export function updateListing(listing, patch) {
  return { ...listing, ...patch };
}

