import { test } from "bun:test";
import { deepStrictEqual, throws } from "node:assert/strict";
import { assertCanPublish, updateListing } from "./listings.js";

const seller = { id: "unverified", identityVerified: false };
const demo = {
  sellerId: seller.id,
  isDemo: true,
  title: "Demo",
  price: 0,
  stockItems: [],
  payoutAccount: null,
};

for (const patch of [
  { stockItems: ["real-item"] },
  { payoutAccount: "real-account" },
]) {
  test(`rejects repurposing a demo with ${Object.keys(patch)[0]}`, () => {
    throws(
      () => assertCanPublish(seller, updateListing(demo, patch)),
      { status: 409, code: "listing.demo_scope_locked" },
    );
    deepStrictEqual(demo.stockItems, []);
    deepStrictEqual(demo.payoutAccount, null);
  });
}

test("keeps the demo title and price editable", () => {
  const updated = updateListing(demo, { title: "Preview", price: 100 });
  deepStrictEqual(updated, { ...demo, title: "Preview", price: 100 });
  assertCanPublish(seller, updated);
});

test("keeps another seller's ordinary listing editable and checked", () => {
  const otherSeller = { id: "other", identityVerified: false };
  const ordinary = { ...demo, sellerId: otherSeller.id, isDemo: false };
  const patch = { stockItems: ["real-item"], payoutAccount: "real-account" };
  const updated = updateListing(ordinary, patch);
  deepStrictEqual(updated, { ...ordinary, ...patch });
  throws(() => assertCanPublish(otherSeller, updated), {
    status: 403,
    code: "seller.identity_unverified",
  });
  assertCanPublish({ ...otherSeller, identityVerified: true }, updated);
});
